'use strict';
(()=>{
const $=s=>document.querySelector(s),I=MaisonIdentity,M=MaisonMusic,C=MaisonCasting,esc=I.esc;
let connection=null,room=null,busy=false,polling=false,failures=0,refreshFrame=null,frame=null,world=null,timer=null,lastMode='',overview=true;
const key='bandlife-coop-tab-v1',savedKey='bandlife-coop-houses-v1',pendingKey='bandlife-coop-pending-v1';
function pendingLogin(mode,name,trio,code){let p;try{p=JSON.parse(sessionStorage.getItem(pendingKey)||'null');}catch{}if(!p||p.mode!==mode||p.name!==name||p.trio!==trio||p.code!==code){p={mode,name,trio,code,token:token()};sessionStorage.setItem(pendingKey,JSON.stringify(p));}return p.token;}
const say=text=>{const el=$('#message');el.textContent=text;el.hidden=false;clearTimeout(timer);timer=setTimeout(()=>el.hidden=true,6500);};
const token=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
function savedRooms(){try{return JSON.parse(localStorage.getItem(savedKey)||'[]').filter(x=>x.code&&x.token).slice(-10);}catch{return [];}}
function remember(){try{sessionStorage.setItem(key,JSON.stringify(connection));const all=savedRooms().filter(x=>x.token!==connection.token);all.push({...connection,name:room.players[room.seat].name});localStorage.setItem(savedKey,JSON.stringify(all.slice(-10)));}catch{say('La reprise après fermeture est indisponible dans ce navigateur. Garde cet onglet ouvert.');}}
async function request(path,body,auth=connection?.token){
 const response=await fetch('/api/coop/'+path,{method:body?'POST':'GET',headers:{authorization:'Bearer '+auth,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(12000)});
 let data;try{data=await response.json();}catch{throw Error('Le serveur coop n’est pas disponible sur cette version du site.');}
 if(!response.ok)throw Error(data.error||'Connexion impossible.');return data;
}
function accept(data){if(room&&room.code===data.code&&data.revision<room.revision)return;const changed=!room||data.code!==room.code||data.revision!==room.revision;room=data;failures=0;$('#connection').classList.remove('offline');$('#connection').textContent='Session sauvegardée · synchronisation active';if(changed)render();}
async function send(input){if(busy)return;busy=true;const command={...input,epoch:room.epoch,commandId:crypto.randomUUID()};setFrameLocked(true);
 try{accept(await request(connection.code+'/command',command));}catch(e){say(e.message);try{accept(await request(connection.code));}catch{offline();}}finally{busy=false;setFrameLocked(locked());}
}
function offline(){failures++;$('#connection').classList.add('offline');$('#connection').textContent='Connexion interrompue · la partie reste sauvegardée · reconnexion automatique';setFrameLocked(true);}
async function poll(){if(!connection||busy||polling||document.hidden)return;polling=true;try{const data=await request(connection.code);accept(data);setFrameLocked(locked());}catch{offline();}finally{polling=false;}}
function locked(){return busy||failures>0||!!room?.concert?.done[room.seat];}
function setFrameLocked(value){if(frame?.contentDocument?.querySelector('#bandlive-view'))frame.contentDocument.querySelector('#bandlive-view').inert=value;const end=$('[data-end]');if(end)end.disabled=value;}
function form(prefix,title,join=false){return `<section class="panel"><h2>${title}</h2><label for="${prefix}Name">Nom de ton groupe</label><input id="${prefix}Name" maxlength="32" placeholder="Les voisins du garage" autocomplete="off"><label for="${prefix}Trio">Ton trio</label><select id="${prefix}Trio">${C.trios.map((t,i)=>`<option value="${i}">${esc(t.name)} · ${t.instruments.join(', ')}</option>`).join('')}</select>${join?`<label for="joinCode">Code de ton partenaire</label><input id="joinCode" maxlength="8" autocapitalize="characters" placeholder="8 caractères" autocomplete="off">`:''}<button class="primary" data-connect="${prefix}">${join?'Rejoindre sa maison':'Créer notre quartier'} →</button></section>`;}
function lobby(){lastMode='';$('#screen').innerHTML=`<section class="intro"><span class="eyebrow">COOP · PROTOTYPE JOUABLE</span><h1>Deux maisons.<br>Un public à conquérir.</h1><p>Chacun prépare son groupe dans sa maison. Vous avancez ensemble, puis jouez vos cartes pendant le même tour de concert. Le tour suivant attend vos deux validations.</p><p class="hint">Cette première session commence en semaine 7, juste avant un concert de voisinage. Un morceau adopté et un projet sont fournis à chaque groupe. La campagne solo et ses sauvegardes restent indépendantes.</p><div class="saved-rooms">${savedRooms().map((x,i)=>`<button data-resume="${i}">Reprendre ${esc(x.name||x.code)} · ${esc(x.code)}</button>`).join('')}</div><div class="lobby-grid">${form('create','Ouvre ta maison')}${form('join','Rejoins ton voisin',true)}</div><p class="hint">Le code invite une seule autre maison. Les deux joueurs doivent pouvoir accéder à ce site.</p></section>`;}
function bandPeople(p){return `<div class="band-people">${p.state.people.map(q=>`<div class="band-person">${I.portrait(q)}<span><b>${esc(q.name)}</b><small>${esc(q.instrument)} · ϟ ${Math.round(q.energy)}</small></span></div>`).join('')}</div>`;}
function house(p,index){const mine=index===room.seat,slots=MaisonHouse.rooms;return `<section class="house ${mine?'mine':''}" id="house${index}"><div class="house-label"><b>${p?esc(p.name):'La maison du voisin'}</b><small>${p?(mine?'TA MAISON':'TON PARTENAIRE'):'À REJOINDRE'}</small></div><div class="house-plan ${p?'':'empty-house'}"><img src="assets/coop-house.svg" alt="Maison avec chambres, salon, studio et garage">${p?p.state.people.map((q,i)=>{const pos=slots[q.room]?.slots?.[i]||slots.salon.slots[i];return `<div class="resident" style="left:${pos[0]/12}%;top:${pos[1]/8}%">${I.portrait(q)}<small>${esc(q.name)}</small></div>`;}).join(''):''}</div></section>`;}
function songs(p,select=false){return `<div class="songs">${p.state.music.songs.filter(x=>!x.archived).map(x=>`<div class="song"><div><strong>${esc(x.title)}</strong><small>${esc(x.genre)} · ${x.turns} tours · ${x.energyPerTurn} énergie/tour</small><small>${M.ready(x)?'✓ Prête pour la scène':x.adopted?'Préparation '+x.preparation+' %':'Écriture '+Math.round(x.progress)+' % · à faire adopter'}</small><meter min="0" max="100" value="${x.adopted?x.preparation:x.progress}"></meter></div>${select&&M.ready(x)?`<button data-song="${x.id}" ${p.selectedSong===x.id?'disabled':''}>${p.selectedSong===x.id?'Choisie ✓':'Jouer cette chanson'}</button>`:''}</div>`).join('')}</div>`;}
function houseControls(p){const choices=[];for(const x of p.state.music.songs){if(x.archived)continue;if(x.adopted&&!M.ready(x))choices.push({action:'practice',songId:x.id,label:'Répéter · '+x.title});if(x.progress<100)choices.push({action:'compose',songId:x.id,label:'Composer · '+x.title});if(!x.adopted&&x.progress>=80&&!x.voteCount)choices.push({action:'trial',songId:x.id,label:'Essayer · '+x.title});}choices.push({action:'rest',songId:'',label:'Se reposer ensemble'});
return `<label for="activity">Programme de ce moment</label><select id="activity" ${p.ready?'disabled':''}>${choices.map(x=>`<option value="${x.action}:${x.songId}" ${p.plan?.action===x.action&&(p.plan?.songId||'')===x.songId?'selected':''}>${esc(x.label)}</option>`).join('')}</select><button data-plan ${p.ready?'disabled':''}>Choisir cette activité</button><div><button class="${p.ready?'':'primary'}" data-ready="${!p.ready}" ${!p.plan?'disabled':''}>${p.ready?'Annuler · je prépare encore':'Prêt pour la suite →'}</button></div><p class="hint">Le temps avance quand les deux groupes sont prêts. Répéter consomme de l’énergie; le repos et la nuit la restaurent.</p>`;}
function render(){
 const p=room.players[room.seat],other=room.players[1-room.seat],stage=room.phase;
 if(stage==='concert')return renderConcert();refreshFrame=null;frame=null;world=null;
 if(stage==='result')return renderResult();lastMode=stage;$('#screen').dataset.mode=stage;
 $('#screen').innerHTML=`<div class="session-bar"><div><span class="eyebrow">COOP · ${stage==='setlist'?'BALANCE AVANT LE SHOW':'LE QUARTIER'}</span><h1>Semaine ${room.week} · ${['10 h','17 h','Minuit'][room.checkpoint]}</h1></div><div class="invite"><span>Invitation</span><code>${room.code}</code><button data-copy>Copier</button></div></div><div class="map-wrap"><div class="map-tools"><button data-map="all">Le quartier</button><button data-map="${room.seat}">Ma maison</button><button data-map="${1-room.seat}">La maison voisine</button></div><div class="neighborhood" id="neighborhood"><div class="houses ${overview?'overview':''}" id="houses">${house(room.players[0],0)}${house(room.players[1],1)}</div></div><div class="street">RUE DES MUSICIENS · CONCERT COMMUN S${room.nextShow}</div></div><div class="panels"><section class="panel"><span class="eyebrow">TA MAISON</span><h2>${esc(p.name)}</h2>${bandPeople(p)}${stage==='lobby'?'<p class="waiting">Partage le code. Ton partenaire peut maintenant rejoindre la maison voisine.</p>':stage==='setlist'?`<p>Choisis ton passage. Chaque groupe joue une chanson, avec sa propre main et son énergie.</p>${p.selectedSong?'<p class="waiting">Ton choix est prêt. En attente de l’autre groupe.</p>':''}`:houseControls(p)}${songs(p,stage==='setlist')}</section><section class="panel"><span class="eyebrow">LA MAISON VOISINE</span><h2>${other?esc(other.name):'Une place pour ton partenaire'}</h2>${other?bandPeople(other)+`<p class="status-row"><span class="status-dot"></span>${other.ready?'Prêt pour la suite ✓':other.selectedSong?'Chanson choisie ✓':other.plan?'Programme choisi · '+({practice:'répétition',compose:'composition',trial:'essai',rest:'repos'}[other.plan.action]):'Prépare son groupe'}</p>`+songs(other):'<p>Le deuxième joueur utilise « Rejoins ton voisin » et saisit votre code.</p>'}<p class="hint">${esc(room.log.at(-1)||'')}</p></section></div>`;
}
function projection(){const g=room.concert.projection,id='coop-'+room.code+'-'+room.week;return {playerId:room.seat+':'+room.players[room.seat].state.people[0].id,people:g.actors,groups:[{id:'maison',name:g.groupName,genre:g.songs[0].style,members:g.actors.map(a=>a.id),archivedAt:null,state:'active',repertoire:g.songs.map(s=>({songId:s.id,active:true,mastery:100}))}],songs:g.songs.map(s=>({...s,ownerGroupId:'maison',authors:[],authorNames:{}})),performance:{id,groupId:'maison',groupName:g.groupName,opportunityId:id,opportunityName:'Le concert des voisins',sourceOpportunity:{id,name:'Le concert des voisins',venue:'garage',crowd:12,styles:g.songs.map(s=>s.style),organizer:{exigence:30},slots:[]},role:'Coop · une chanson par groupe',preview:false,status:'playing',actors:g.actors,result:{score:0},bandLive:{game:g}},showEventId:id,season:{opportunities:[]},eventArchive:[],bookings:[],showHistory:[]};}
function renderConcert(){const c=room.concert,p=room.players[room.seat],partner=room.players[1-room.seat],aim=c.aim[1-room.seat],fan=c.projection.fans.find(f=>f.id===aim);world=projection();
 if(lastMode!=='concert'){$('#screen').innerHTML='<div class="concert-bar"><div><span class="eyebrow">BANDLIVE · COOP</span><h2 id="concertTitle"></h2><p id="concertStatus" aria-live="polite"></p></div><button data-end class="primary">Fin de mon tour →</button></div><iframe class="stage-frame" id="coopStage" title="Concert coop BandLive" src="show-module/coop.html" allow="autoplay; fullscreen"></iframe>';frame=$('#coopStage');lastMode='concert';}
 $('#concertTitle').textContent=p.name+' + '+partner.name+' · Tour '+c.round;
 $('#concertStatus').textContent=c.done[room.seat]?'Ton groupe a terminé · le partenaire joue encore.':c.done[1-room.seat]?'Ton partenaire a terminé · à toi de finir.':fan?partner.name+' prépare une carte sur '+fan.name+'.':'Vous pouvez jouer vos cartes tous les deux. Validez ensuite la fin du tour.';
 $('[data-end]').disabled=locked();refreshFrame?.();setFrameLocked(locked());
}
function renderResult(){lastMode='result';const p=room.players[room.seat],won=room.concert.phase==='won';$('#screen').innerHTML=`<section class="panel result"><span class="eyebrow">LE CONCERT DES VOISINS · S${room.week}</span><h1>${won?'Une scène, une victoire.':'Le public en voulait encore.'}</h1><p>${won?'Les deux groupes ont conquis le public. Chacun choisit une carte pour un de ses musiciens.':'La tentative est terminée. Retrouvez vos maisons pour préparer le prochain rendez-vous ensemble.'}</p>${won&&!p.rewardClaimed?`<label for="rewardPerson">Le musicien qui reçoit la carte</label><select id="rewardPerson">${p.state.people.map(q=>`<option value="${q.id}">${esc(q.name)} · ${esc(q.instrument)}</option>`).join('')}</select><div id="rewardCards" class="reward-grid"></div>`:won?'<p>Récompense reçue ✓</p>':''}<button data-return class="primary" ${p.ready||won&&!p.rewardClaimed?'disabled':''}>${p.ready?'En attente du voisin…':'Retourner dans nos maisons →'}</button><p class="hint">L’énergie finale des musiciens est conservée. Le prochain concert laisse quatre semaines pour se préparer.</p></section>`;if($('#rewardPerson'))renderRewards();}
function renderRewards(){const q=room.players[room.seat].state.people.find(p=>p.id===$('#rewardPerson').value);$('#rewardCards').innerHTML=M.cards.choices(q).map(id=>`<button data-reward="${id}"><b>${esc(M.CARDS[id].name)}</b><small>${esc(M.CARDS[id].text||M.CARDS[id].description||'')}</small></button>`).join('');}
window.MaisonCoopLive={connect(caller){if(!frame||caller!==frame.contentWindow)throw Error('Scène inconnue.');return {get world(){return world;},command:send,subscribe(fn){refreshFrame=fn;},locked,ready(){setFrameLocked(locked());},notify:say,returnHome(){say('Terminez ce concert ensemble pour rentrer dans les maisons.');}};}};
document.addEventListener('change',e=>{if(e.target.id==='rewardPerson')renderRewards();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.connect){if(busy)return;const mode=b.dataset.connect,name=$('#'+mode+'Name').value.trim(),trio=Number($('#'+mode+'Trio').value),code=mode==='join'?$('#joinCode').value.trim().toUpperCase():null;if(!name)return say('Donne un nom à ton groupe.');busy=true;b.disabled=true;try{const auth=pendingLogin(mode,name,trio,code),data=await request(mode==='join'?code+'/join':'create',{name,trio},auth);connection={code:data.code,token:auth};accept(data);remember();sessionStorage.removeItem(pendingKey);}catch(err){say(err.message);b.disabled=false;}finally{busy=false;}return;}
 if(b.dataset.resume!==undefined){connection=savedRooms()[Number(b.dataset.resume)];if(!connection)return;try{accept(await request(connection.code));remember();}catch(err){say(err.message);connection=null;}return;}
 if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(room.code);say('Code copié : '+room.code);}catch{say('Votre code : '+room.code);}return;}
 if(b.dataset.map){overview=b.dataset.map==='all';$('#houses').classList.toggle('overview',overview);if(!overview)$('#house'+b.dataset.map).scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});return;}
 if(b.hasAttribute('data-plan')){const [activity,...song]=$('#activity').value.split(':');return send({action:'plan',activity,songId:song.join(':')});}
 if(b.hasAttribute('data-ready'))return send({action:'ready',ready:b.dataset.ready==='true'});
 if(b.dataset.song)return send({action:'song',songId:b.dataset.song});
 if(b.hasAttribute('data-end'))return send({action:'end'});
 if(b.dataset.reward)return send({action:'reward',personId:$('#rewardPerson').value,cardId:b.dataset.reward});
 if(b.hasAttribute('data-return'))return send({action:'return'});
});
try{connection=JSON.parse(sessionStorage.getItem(key)||'null');}catch{}lobby();if(connection)poll();setInterval(poll,1200);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
